import type { NextRequest } from "next/server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const AUDIO_BASE64 = "";
const AUDIO = Buffer.from(AUDIO_BASE64, "base64");

const commonHeaders = {
  "Accept-Ranges": "bytes",
  "Cache-Control": "public, max-age=31536000, immutable",
  "Content-Type": "audio/mpeg",
};

export async function GET(request: NextRequest) {
  const range = request.headers.get("range");

  if (!range) {
    return new Response(AUDIO, {
      status: 200,
      headers: {
        ...commonHeaders,
        "Content-Length": String(AUDIO.length),
      },
    });
  }

  const match = /^bytes=(\d*)-(\d*)$/.exec(range.trim());
  if (!match) {
    return new Response(null, {
      status: 416,
      headers: {
        ...commonHeaders,
        "Content-Range": `bytes */${AUDIO.length}`,
      },
    });
  }

  const requestedStart = match[1] ? Number(match[1]) : undefined;
  const requestedEnd = match[2] ? Number(match[2]) : undefined;
  let start = requestedStart ?? 0;
  let end = requestedEnd ?? AUDIO.length - 1;

  if (requestedStart === undefined && requestedEnd !== undefined) {
    start = Math.max(0, AUDIO.length - requestedEnd);
    end = AUDIO.length - 1;
  }

  if (
    !Number.isSafeInteger(start) ||
    !Number.isSafeInteger(end) ||
    start < 0 ||
    end < start ||
    start >= AUDIO.length
  ) {
    return new Response(null, {
      status: 416,
      headers: {
        ...commonHeaders,
        "Content-Range": `bytes */${AUDIO.length}`,
      },
    });
  }

  end = Math.min(end, AUDIO.length - 1);
  const chunk = AUDIO.subarray(start, end + 1);

  return new Response(chunk, {
    status: 206,
    headers: {
      ...commonHeaders,
      "Content-Length": String(chunk.length),
      "Content-Range": `bytes ${start}-${end}/${AUDIO.length}`,
    },
  });
}
